                    ComInternaPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (CominternaUsuario) to the collection in $obj3 (ComInterna)
                $obj3->addCominternaUsuario($obj1);

            } // if joined row is not null

                // Add objects for joined RolusuarioCominterna rows

                $key4 = RolusuarioCominternaPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = RolusuarioCominternaPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = RolusuarioCominternaPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    RolusuarioCominternaPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (CominternaUsuario) to the collection in $obj4 (RolusuarioCominterna)
                $obj4->addCominternaUsuario($obj1);

            } // if joined row is not null

                // Add objects for joined CargoUsuario rows

                $key5 = CargoUsuarioPeer::getPrimaryKeyHashFromRow($row, $startcol5);
                if ($key5 !== null) {
                    $obj5 = CargoUsuarioPeer::getInstanceFromPool($key5);
                    if (!$obj5) {
    
                        $cls = CargoUsuarioPeer::getOMClass();

                    $obj5 = new $cls();
                    $obj5->hydrate($row, $startcol5);
                    CargoUsuarioPeer::addInstanceToPool($obj5, $key5);
                } // if $obj5 already loaded

                // Add the $obj1 (CominternaUsuario) to the collection in $obj5 (CargoUsuario)
                $obj5->addCominternaUsuario($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }

