        if ($cols) {
            $dbMap = Propel::getDatabaseMap(CominternaUsuarioPeer::DATABASE_NAME);
            $tableMap = $dbMap->getTable(CominternaUsuarioPeer::TABLE_NAME);

            if (! is_array($cols)) {
                $cols = array($cols);
            }

            foreach ($cols as $colName) {
                if ($tableMap->hasColumn($colName)) {
                    $get = 'get' . $tableMap->getColumn($colName)->getPhpName();
                    $columns[$colName] = $obj->$get();
                }
            }
        } else {

        }

        return BasePeer::doValidate(CominternaUsuarioPeer::DATABASE_NAME, CominternaUsuarioPeer::TABLE_NAME, $columns);
    }

    /**
