     *
     * @param int $pk the primary key.
     * @param      PropelPDO $con the connection to use
     * @return CominternaUsuario
     */
    public static function retrieveByPK($pk, PropelPDO $con = null)
    {

        if (null !== ($obj = CominternaUsuarioPeer::getInstanceFromPool((string) $pk))) {
            return $obj;
        }

        if ($con === null) {
            $con = Propel::getConnection(CominternaUsuarioPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria = new Criteria(CominternaUsuarioPeer::DATABASE_NAME);
        $criteria->add(CominternaUsuarioPeer::COMINTERNAUSUARIO_ID, $pk);

        $v = CominternaUsuarioPeer::doSelect($criteria, $con);

        return !empty($v) > 0 ? $v[0] : null;
    }

    /**
     * Retrieve multiple objects by pkey.
     *
     * @param      array $pks List of primary keys
     * @param      PropelPDO $con the connection to use
     * @return CominternaUsuario[]
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function retrieveByPKs($pks, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(CominternaUsuarioPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $objs = null;
        if (empty($pks)) {
            $objs = array();
        } else {
            $criteria = new Criteria(CominternaUsuarioPeer::DATABASE_NAME);
            $criteria->add(CominternaUsuarioPeer::COMINTERNAUSUARIO_ID, $pks, Criteria::IN);
            $objs = CominternaUsuarioPeer::doSelect($criteria, $con);
        }

        return $objs;
    }

